import fs from 'node:fs';
import { spawnSync } from 'node:child_process';

const readBootId = () => fs.readFileSync('/proc/sys/kernel/random/boot_id', 'utf8').trim();
const readStartTime = (pid) => {
  try {
    const raw = fs.readFileSync(`/proc/${pid}/stat`, 'utf8');
    return Number(raw.slice(raw.lastIndexOf(')') + 2).trim().split(/\s+/)[19]);
  } catch { return null; }
};
const readPidNs = (pid) => {
  try { return fs.readlinkSync(`/proc/${pid}/ns/pid`); } catch { return null; }
};

// Config A: Exact command in v3-r1 section 9.3 / probe_pidns_containment.py:
// bwrap --dev-bind / / --unshare-pid --die-with-parent (WITHOUT --proc /proc)
const cfgA = spawnSync('bwrap', [
  '--dev-bind', '/', '/', '--unshare-pid', '--die-with-parent',
  'node', '-e',
  `const fs = require('node:fs');
   const pid = process.pid;
   const stat = fs.readFileSync('/proc/' + pid + '/stat', 'utf8').slice(0, 40).trim();
   let fdErr = null;
   try { fs.readdirSync('/proc/' + pid + '/fd'); } catch (e) { fdErr = e.code; }
   console.log(JSON.stringify({ innerPid: pid, procPidStatOnHostProc: stat, readProcFdCode: fdErr }));`
], { encoding: 'utf8' });
const cfgAData = JSON.parse(cfgA.stdout.trim());
const hostSeesPid2Alive = readStartTime(cfgAData.innerPid) !== null;

// Config B: With --proc /proc AND pidNs check per section 5.1 ("pidNs khac -> unknown") & section 6.6 ("chi dead, khong bao gio unknown")
const cfgB = spawnSync('bwrap', [
  '--dev-bind', '/', '/', '--proc', '/proc', '--unshare-pid', '--die-with-parent',
  'node', '-e',
  `const fs = require('node:fs');
   const raw = fs.readFileSync('/proc/' + process.pid + '/stat', 'utf8');
   const st = Number(raw.slice(raw.lastIndexOf(')') + 2).trim().split(/\\s+/)[19]);
   const pidNs = fs.readlinkSync('/proc/' + process.pid + '/ns/pid');
   console.log(JSON.stringify({ pid: process.pid, startTime: st, pidNs }));`
], { encoding: 'utf8' });
const deadAttemptHolder = JSON.parse(cfgB.stdout.trim());
const hostPidNs = readPidNs(process.pid);
const judgeFromHostWithPidNs = deadAttemptHolder.pidNs !== hostPidNs ? 'unknown' : 'dead';
const reclaimAllowedUnderSection6_6 = judgeFromHostWithPidNs === 'dead';

// Config C: With --proc /proc WITHOUT pidNs check (as in probe-hot-reclaim.mjs)
const liveHostRecord = { pid: process.pid, startTime: readStartTime(process.pid), bootId: readBootId() };
const cfgC = spawnSync('bwrap', [
  '--dev-bind', '/', '/', '--proc', '/proc', '--unshare-pid', '--die-with-parent',
  'node', '-e',
  `const holder = ${JSON.stringify(liveHostRecord)};
   let alive = true;
   try { process.kill(holder.pid, 0); } catch (e) { if (e.code === 'ESRCH') alive = false; }
   console.log(JSON.stringify({ liveHostPid: holder.pid, innerKill0SeesAlive: alive, innerJudgesLiveHostHolder: alive ? 'alive' : 'dead' }));`
], { encoding: 'utf8' });
const cfgCData = JSON.parse(cfgC.stdout.trim());

console.log(JSON.stringify({
  configA_withoutProcMount: { ...cfgAData, hostSeesPid2AsLiveKernelThread: hostSeesPid2Alive, permanentDeadlockOnCrash: hostSeesPid2Alive },
  configB_withProcMountAndPidNsCheck: { deadAttemptHolder, hostPidNs, judgeFromHostWithPidNs, reclaimAllowedUnderSection6_6, permanentDeadlockOnCrash: !reclaimAllowedUnderSection6_6 },
  configC_withProcMountWithoutPidNsCheck: { ...cfgCData, liveHostLockStolenByAttempt: cfgCData.innerJudgesLiveHostHolder === 'dead' }
}));

