import fs from 'node:fs';
import net from 'node:net';
import path from 'node:path';
import { spawn, spawnSync } from 'node:child_process';
import { prepareBwrapSync } from '/home/vantt/projects/forgentX/src/runner/dispatch/confinement/drivers/bwrap.mjs';

const dir = process.argv[2];

const baseReq = {
  dispatchId: 'd1',
  context: { repoRoot: dir, stateRoot: path.join(dir, '.fgos'), timeoutMs: 5000 },
  invocation: { command: 'true', args: [], cwd: dir, env: {}, resourceBindings: [] },
  policy: { mode: 'required', controls: { hostWrite: 'deny', hostRead: 'allow', networkEgress: 'allow', process: 'host' } }
};
const normalPrep = prepareBwrapSync({ resources: [] }, baseReq, {});
const blindPrep = prepareBwrapSync(
  { resources: [{ resource: 'own-assignment', hostTarget: dir, executionTarget: { path: dir }, access: 'read-only' }] },
  { ...baseReq, policy: { mode: 'required', controls: { hostWrite: 'deny', hostRead: 'blind', networkEgress: 'allow', process: 'host' } } },
  {}
);

const sockPath = path.join(dir, 'host-daemon.sock');
let daemonSpawnedPid = null;
const server = net.createServer((conn) => {
  conn.on('data', () => {
    const child = spawn('node', ['-e', 'setInterval(() => {}, 1000)'], { detached: true, stdio: 'ignore' });
    child.unref();
    daemonSpawnedPid = child.pid;
    conn.end(String(child.pid));
  });
});
await new Promise((r) => server.listen(sockPath, r));

const gate = spawn('bwrap', [
  '--dev-bind', '/', '/', '--proc', '/proc', '--unshare-pid', '--die-with-parent',
  'node', '-e',
  `const net = require('node:net');
   const c = net.connect(${JSON.stringify(sockPath)}, () => c.write('spawn'));
   c.on('data', () => { setInterval(() => {}, 1000); });`
], { stdio: 'ignore' });

await new Promise((r) => setTimeout(r, 250));
process.kill(gate.pid, 'SIGKILL');
await new Promise((r) => setTimeout(r, 150));

let escapedAliveAfterGateSigkill = false;
if (daemonSpawnedPid) {
  try { process.kill(daemonSpawnedPid, 0); escapedAliveAfterGateSigkill = true; } catch {}
  try { process.kill(daemonSpawnedPid, 'SIGKILL'); } catch {}
}
server.close();

const leakMarker = path.join(dir, 'blind-no-diewithparent.txt');
const gateNoDie = spawn('python3', ['-c', `
import ctypes, os, subprocess, time
libc = ctypes.CDLL("libc.so.6")
def set_pdeath(): libc.prctl(1, 9)
p = subprocess.Popen(
    ["bwrap", "--dev-bind", "/", "/", "--proc", "/proc", "--unshare-pid",
     "python3", "-c",
     "import os, time\\nif os.fork() == 0:\\n os.setsid()\\n while True:\\n  open(" + ${JSON.stringify(JSON.stringify(leakMarker))} + ", 'w').write(str(time.time()))\\n  time.sleep(0.03)\\ntime.sleep(30)"],
    preexec_fn=set_pdeath
)
time.sleep(30)
`]);
await new Promise((r) => setTimeout(r, 300));
process.kill(gateNoDie.pid, 'SIGKILL');
await new Promise((r) => setTimeout(r, 150));
const t1 = Number(fs.readFileSync(leakMarker, 'utf8'));
await new Promise((r) => setTimeout(r, 120));
const t2 = Number(fs.readFileSync(leakMarker, 'utf8'));
const leakedWithoutDieWithParent = t2 > t1;
spawnSync('pkill', ['-9', '-f', leakMarker]);

const ttyCheck = spawnSync('python3', ['-c', `
import os, pty, subprocess
master, slave = pty.openpty()
def setup_ctty():
    os.setsid()
    import fcntl, termios
    fcntl.ioctl(0, termios.TIOCSCTTY, 0)
p = subprocess.Popen(
    ["bwrap", "--dev-bind", "/", "/", "--proc", "/proc", "--unshare-pid", "--die-with-parent",
     "python3", "-c", "import os; print(f'{os.getpgrp()}:{os.tcgetpgrp(0)}')"],
    stdin=slave, stdout=subprocess.PIPE, stderr=subprocess.PIPE, preexec_fn=setup_ctty
)
os.close(slave)
out, _ = p.communicate(timeout=3)
os.close(master)
print(out.decode().strip())
`], { encoding: 'utf8' });

console.log(JSON.stringify({
  productionBwrapNormalHasUnsharePid: normalPrep.invocation.args.includes('--unshare-pid'),
  productionBwrapNormalHasDieWithParent: normalPrep.invocation.args.includes('--unshare-pid') && normalPrep.invocation.args.includes('--die-with-parent'),
  productionBwrapBlindHasUnsharePid: blindPrep.invocation.args.includes('--unshare-pid'),
  productionBwrapBlindHasDieWithParent: blindPrep.invocation.args.includes('--die-with-parent'),
  leakedGrandchildWhenDieWithParentOmitted: leakedWithoutDieWithParent,
  hostSocketSpawnedPid: daemonSpawnedPid,
  escapedProcessAliveAfterGateSigkillWithDieWithParent: escapedAliveAfterGateSigkill,
  innerGetpgrpAndTcgetpgrpWhenHostSetsForeground: ttyCheck.stdout.trim()
}));

